    let v1 = variance_of(y1)
    print("case 1: y = x - x\n")
    print("  value      = "); println(y1)     // 0.0 (trivial)
    print("  var        = "); println(v1)     // compiler: 2·var(x) ≈ 0.02? truth: 0
    print("  truth      = 0.0\n")
    print("  var(x)     = "); println(variance_of(x.value))   // reference
    println("")

    // CASE 2: y = a·b - a·b where a, b separately measured (still correlated).
    let a: Knowledge<f64> = measure(2.0, uncertainty: 0.05)
    let b: Knowledge<f64> = measure(3.0, uncertainty: 0.05)
    let prod1 = a.value * b.value
    let prod2 = a.value * b.value
    let y2 = prod1 - prod2
    let v2 = variance_of(y2)
    print("case 2: y = a·b − a·b\n")
    print("  value      = "); println(y2)
    print("  var        = "); println(v2)
    print("  truth      = 0.0\n")
    println("")

    // CASE 3: same variable through different paths.
    // y = (x + 1) - (x + 1) — topologically distinct intermediates,
    // algebraically zero.
    let path_a = x.value + 1.0
    let path_b = x.value + 1.0
    let y3 = path_a - path_b
    let v3 = variance_of(y3)
    print("case 3: y = (x+1) − (x+1)\n")
    print("  value      = "); println(y3)
    print("  var        = "); println(v3)
    print("  truth      = 0.0\n")
    println("")

    // Diagnosis.
    // σ = 0.1 → σ² = 0.01. Covariance-blind compiler predicts:
    //   Var(x - x) = 2·σ² = 0.02
    //   Var((x+1) - (x+1)) = 2·σ² = 0.02
    //   Var(a·b - a·b) = 2·(a²·σ_b² + b²·σ_a²) = 2·(4·0.0025 + 9·0.0025) = 0.065
    // Covariance-aware compiler would give 0 for all three.
    let sigma_sq: f64 = 0.01   // (0.1)² = σ² for x
    let expected_blind_v1 = 2.0 * sigma_sq                             // 0.02
    let expected_blind_v3 = 2.0 * sigma_sq                             // 0.02
    let expected_blind_v2 = 2.0 * (4.0 * 0.0025 + 9.0 * 0.0025)        // 0.065

    println("=== β diagnosis ===")
    print("  σ² = 0.01.  If covariance-blind, predicted:\n")
    print("    Var(x - x)           = "); println(expected_blind_v1)
    print("    Var((x+1)-(x+1))     = "); println(expected_blind_v3)
    print("    Var(a·b − a·b)       = "); println(expected_blind_v2)
    print("  Observed:\n")
    print("    v1 = "); println(v1)
    print("    v2 = "); println(v2)
    print("    v3 = "); println(v3)

    // Tolerance: 1% relative (inline, nested fn not allowed in this compiler).
    let d1 = v1 - expected_blind_v1
    let a_d1 = if d1 < 0.0 { 0.0 - d1 } else { d1 }
    let ok_v1 = a_d1 < 0.01 * expected_blind_v1

    let d2 = v2 - expected_blind_v2
    let a_d2 = if d2 < 0.0 { 0.0 - d2 } else { d2 }
    let ok_v2 = a_d2 < 0.01 * expected_blind_v2

    let d3 = v3 - expected_blind_v3
    let a_d3 = if d3 < 0.0 { 0.0 - d3 } else { d3 }
    let ok_v3 = a_d3 < 0.01 * expected_blind_v3

    println("")
    // Truth-aware: all three must be ~0 under FO sensitivity GUM (β¹⁰).
    let t1 = if v1 < 0.0 { 0.0 - v1 } else { v1 }
    let t2 = if v2 < 0.0 { 0.0 - v2 } else { v2 }
    let t3 = if v3 < 0.0 { 0.0 - v3 } else { v3 }
    let aware = t1 < 1.0e-12 && t2 < 1.0e-12 && t3 < 1.0e-12
    if aware {
        println("BETA10_COVARIANCE_AWARE: Var(f-f)=0 on all three cases.")
        println("  FO sensitivity-difference GUM is live (slot identity + sens cancel).")
    } else {
        if ok_v1 && ok_v2 && ok_v3 {
            println("CONFIRMED: compiler is covariance-blind on all three cases.")
            println("  β's core claim is directly verified.")
            println("  Var(f - f) = 2·Var(f) instead of 0.")
        } else {
            println("PARTIAL: neither fully blind nor fully aware — inspect observed vars.")
        }
    }
    print("DIAGNOSTIC_COMPLETE\n")
}

//@ run-pass
// tests/run-pass/viz_editor_scene.sio - minimal native scene editor proof
//
// Expected output includes:
//   data-viz-tag="7202"
//   VIZ_EDITOR_SCENE_PASS

use display::canvas::{Canvas, canvas_clear}
use display::event::{Event, EV_KEY_PRESS, KEY_RIGHT, KEY_DOWN}
use viz::audit::{viz_audit_hash, viz_audit_node_hash}
use viz::editor::{
    viz_editor_resize_selected, viz_editor_set_selected_tag, viz_editor_set_selected_value,
    viz_editor_trace_events,
}
use viz::inspector::{viz_inspector_draw, viz_inspector_select, viz_inspector_draw_node_highlights}
use viz::ir::{
    viz_scene_new, viz_layout_rect, viz_style_rgb,
    viz_add_button, viz_add_slider, viz_scene_set_tag,
}
use viz::viz_canvas::{viz_canvas_render_scene}
use viz::viz_html::{viz_html_emit_scene}

fn make_canvas(w: i64, h: i64) -> Canvas with Alloc {
    let pix = heap_alloc(w * h * 8) as *mut i64
    Canvas { pixels: pix, width: w, height: h }
}

fn read_px(c: &Canvas, x: i64, y: i64) -> i64 {
    read_i64(c.pixels, y * c.width + x)
}

fn ev(kind: i64, key: i64, x: i64, y: i64, mods: i64) -> Event {
    Event { kind: kind, key: key, x: x, y: y, mods: mods }
}

fn main() with IO, Alloc, Mut, Div {
    var scene = viz_scene_new()
    var label: [i8; 64] = [0; 64]
    label[0] = 69
    label[1] = 100
    label[2] = 105
    label[3] = 116

    let button = viz_add_button(&!scene, &label, 4, viz_layout_rect(12, 12, 48, 18), viz_style_rgb(90, 180, 240))
    let slider = viz_add_slider(&!scene, viz_layout_rect(72, 12, 90, 18), 0.25, 0.0, 1.0, viz_style_rgb(240, 190, 80))
    viz_scene_set_tag(&!scene, button, 7201)
    viz_scene_set_tag(&!scene, slider, 7200)

    var c = make_canvas(280, 150)
    canvas_clear(&!c, 5, 6, 7)
    viz_canvas_render_scene(&scene, &!c)
    viz_inspector_draw(&scene, &!c, 18, 48, 226, 92)

    let selected = viz_inspector_select(&!scene, 18, 48, 226, 92, 30, 133)
    assert(selected == slider)
    let before_node = viz_audit_node_hash(&scene, slider)
    assert(before_node != 0)

    assert(viz_editor_set_selected_tag(&!scene, 7202))
    assert(viz_editor_set_selected_value(&!scene, 0.75))
    let resize_before_w = scene.nodes[slider as usize].layout.w
    let resize_before_h = scene.nodes[slider as usize].layout.h
    assert(viz_editor_resize_selected(&!scene, 10, 4, 8, 8))
    assert(scene.nodes[slider as usize].tag == 7202)
    assert(scene.nodes[slider as usize].value == 0.75)
    let direct_w = scene.nodes[slider as usize].layout.w
    let direct_h = scene.nodes[slider as usize].layout.h
    assert(direct_w == resize_before_w + 10)
    assert(direct_h == resize_before_h + 4)

    var events: [Event; 32] = [ev(0, 0, 0, 0, 0); 32]
    events[0] = ev(EV_KEY_PRESS, KEY_RIGHT, 0, 0, 0)
    events[1] = ev(EV_KEY_PRESS, KEY_DOWN, 0, 0, 0)
    events[2] = ev(EV_KEY_PRESS, KEY_RIGHT, 0, 0, 1)
    let trace = viz_editor_trace_events(&!scene, &events, 3, 3)

    assert(trace.count == 3)
    assert(trace.frames[0].changed)
    assert(trace.frames[1].changed)
    assert(trace.frames[2].changed)
    assert(trace.frames[2].selected_node == slider)
    assert(trace.frames[2].node_hash == viz_audit_node_hash(&scene, slider))
    assert(trace.frames[2].audit_hash == viz_audit_hash(&scene))
    assert(scene.nodes[slider as usize].layout.x == 75)
    assert(scene.nodes[slider as usize].layout.y == 15)
    assert(scene.nodes[slider as usize].layout.w == direct_w + 3)
    assert(viz_audit_node_hash(&scene, slider) != before_node)

    canvas_clear(&!c, 5, 6, 7)
    viz_canvas_render_scene(&scene, &!c)
    viz_inspector_draw_node_highlights(&scene, &!c)
    viz_inspector_draw(&scene, &!c, 18, 48, 226, 92)
    assert(read_px(&c, 73, 10) != 0)
    assert(read_px(&c, 30, 133) != 0)

    viz_html_emit_scene(&scene, 220, 80)

    heap_free(c.pixels as *mut i8)
    println("VIZ_EDITOR_SCENE_PASS")
}

//@ run-pass
// tests/run-pass/viz_interaction_time.sio - Visual IR interaction state smoke test
//
// Expected output:
//   VIZ_INTERACTION_TIME_PASS

use display::canvas::{Canvas, canvas_clear}
use viz::ir::{viz_scene_new, viz_layout_rect, viz_add_control, viz_add_trajectory, viz_scene_pointer_down, viz_scene_pointer_update, viz_scene_set_time, VIZ_CONTROL_SLIDER}
use viz::viz_canvas::{viz_canvas_render_scene}
use viz::physchem::{trajectory_spiral}

fn make_canvas(w: i64, h: i64) -> Canvas with Alloc {
    let pix = heap_alloc(w * h * 8) as *mut i64
    Canvas { pixels: pix, width: w, height: h }
}

fn read_px(c: &Canvas, x: i64, y: i64) -> i64 {
    read_i64(c.pixels, y * c.width + x)
}

fn main() with IO, Alloc, Mut, Div {
    var scene = viz_scene_new()
    let tr = trajectory_spiral(20)
    let traj_node = viz_add_trajectory(&!scene, tr, viz_layout_rect(10, 10, 140, 70))
    let slider = viz_add_control(&!scene, VIZ_CONTROL_SLIDER, viz_layout_rect(10, 92, 140, 20), 0.0, 0.0, 19.0)
    assert(traj_node == 0)
    assert(slider == 1)

    viz_scene_set_time(&!scene, 0.0)
    var c0 = make_canvas(180, 130)
    canvas_clear(&!c0, 0, 0, 0)
    viz_canvas_render_scene(&scene, &!c0)
    let start_cursor_px = read_px(&c0, 92, 45)
    heap_free(c0.pixels as *mut i8)

    let selected = viz_scene_pointer_down(&!scene, 10, 100)
    assert(selected == slider)
    assert(scene.selected_node == slider)
    let updated = viz_scene_pointer_update(&!scene, 150, 100)
    assert(updated == slider)
    assert(scene.nodes[slider as usize].value == 19.0)
    assert(scene.time == 19.0)

    var c1 = make_canvas(180, 130)
    canvas_clear(&!c1, 0, 0, 0)
    viz_canvas_render_scene(&scene, &!c1)
    assert(read_px(&c1, 100, 41) != 0)
    heap_free(c1.pixels as *mut i8)

    let clamped = viz_scene_pointer_update(&!scene, 0, 100)
    assert(clamped == slider)
    assert(scene.nodes[slider as usize].value == 0.0)
    assert(scene.time == 0.0)
    assert(start_cursor_px != 0)

    println("VIZ_INTERACTION_TIME_PASS")
}

